diagrams.source:
digraph Lifecycle {
  rankdir=LR;
  draft [label="New proposed revision: Draft"];
  approved [label="Accepted revision: Approved"];
  implemented [label="Exact current revision: Implemented"];
  revised [label="New accepted revision: Approved"];
  evidence [label="Baseline-specific verification"];
  draft -> approved [label="reviewed Apply"];
  approved -> implemented [label="exact-match snapshot commit"];
  implemented -> approved [label="last automated support cleared"];
  implemented -> revised [label="Apply meaningful edit"];
  implemented -> evidence [style=dashed, label="separate outcome"];
}
